package io.github.diodeme.ji.ai;

import java.time.Duration;
import java.util.Map;
import java.util.Optional;

/** Sanitized structured provider failure; no credential or response body is retained. */
public record ProviderFailure(String code, Map<String, String> parameters, Optional<Duration> retryAfter) {
    public ProviderFailure {
        if (code == null || code.isBlank()) throw new IllegalArgumentException("provider error code must not be blank");
        parameters = Map.copyOf(parameters);
        retryAfter = retryAfter == null ? Optional.empty() : retryAfter;
        retryAfter.ifPresent(value -> {
            if (value.isNegative()) throw new IllegalArgumentException("retryAfter must be non-negative");
        });
    }
}
